import io.wayfarer.rpg.core.*;
import static io.wayfarer.rpg.core.CareerSystem.*;
import java.io.*;
import java.util.*;

public final class PactTests {
    private static int count;
    private static void check(boolean v,String why){count++;if(!v)throw new AssertionError(why);}
    private static void near(float a,float b,String why){check(Math.abs(a-b)<.05f,why+": "+a+" vs "+b);}
    private static ActionGame game(int job,int spec){ActionGame g=new ActionGame();g.experience[0]=160;check(g.chooseCareer(job,spec,0,true),"select optional pact");g.start(91);arena(g);return g;}
    private static void arena(ActionGame g){g.enemies.clear();g.blocks.clear();g.shots.clear();g.x=560;g.y=600;g.enemies.add(new ActionGame.Enemy(g.nextId++,0,620,600,1000));g.enemies.get(0).stun=1;g.invulnerable=0;}
    private static void tick(ActionGame g){for(ActionGame.Enemy e:g.enemies)e.stun=1;g.hitStop=0;g.update(1f/60f,new ActionGame.Input());g.signals.clear();}
    private static void hurt(ActionGame g,float damage){g.invulnerable=0;g.shots.add(new ActionGame.Shot(g.x,g.y,0,0,damage,false));tick(g);}
    private static void hit(ActionGame g,float damage){ActionGame.Enemy e=g.enemies.get(0);g.shots.add(new ActionGame.Shot(e.x,e.y,0,0,damage,true));tick(g);}
    private static byte[] edit(byte[] data,String key,String value)throws Exception{Properties p=new Properties();p.load(new ByteArrayInputStream(data));p.setProperty(key,value);ByteArrayOutputStream out=new ByteArrayOutputStream();p.store(out,"");return out.toByteArray();}
    private static void reject(byte[] data,String key,String value)throws Exception{boolean bad=false;try{ActionSave.decode(edit(data,key,value));}catch(IOException e){bad=true;}check(bad,"reject "+key+"="+value);}
    private static void choices()throws Exception{
        ActionGame g=new ActionGame();check(!g.pactEnabled(),"new game opts out");check(!g.chooseCareer(POLICE,0,0,true),"pact level gate without specialization");g.experience[0]=160;check(!g.chooseCareer(3,1,0,true),"unavailable career refused");check(g.chooseCareer(POLICE,0,0,true),"level-three optional pact without specialization");g.selectHero(1);check(!g.pactEnabled(),"independent preset pact");g.selectHero(0);check(g.pactEnabled(),"original choice retained");g.chooseCareer(DOCTOR,0,0);check(!g.pactEnabled(),"changing career does not silently accept another cost");
        g.chooseCareer(DOCTOR,1,4,true);g.start(1);check(!g.chooseCareer(DOCTOR,1,4,false),"cannot remove debt during run");g.pause();check(!g.professionPact(),"cannot cast paused");g.abandon();g.returnCamp();check(g.chooseCareer(DOCTOR,1,4,false)&&!g.pactEnabled(),"explicit camp opt-out");
        for(int job=POLICE;job<=REPORTER;job++)check(!ProfessionPacts.TEMPERAMENTS[job].isEmpty()&&!ProfessionPacts.LINES[job].isEmpty()&&ProfessionPacts.DETAILS[job].contains("代价"),"each ordinary career has character and explicit price");
    }
    private static void effects()throws Exception{
        ActionGame g=game(POLICE,1);float hp=g.hp;check(g.professionPact(),"police sentence");near(hp-g.hp,g.maxHp()*.12f,"life cost retained as balance");g.enemies.get(0).hp=290;ActionGame.Enemy boss=new ActionGame.Enemy(g.nextId++,3,740,600,1000);boss.hp=290;boss.pactMark=g.pactTime;boss.pactTick=1;g.enemies.add(boss);hit(g,20);check(g.enemies.size()==1&&g.enemies.get(0)==boss,"sentence executes marked wounded normal enemy");hit(g,20);near(boss.hp,258,"boss takes enhanced damage, never threshold execution");hp=g.hp;hurt(g,20);near(hp-g.hp,9.5f,"police retains defensive cost tradeoff");check(!g.professionPact(),"cooldown prevents replay");
        g=game(SOLDIER,0);float power=g.damage();ActionGame.Enemy first=g.enemies.get(0);ActionGame.Enemy second=new ActionGame.Enemy(g.nextId++,0,685,600,1000);second.hp=10;g.enemies.add(second);check(g.professionPact(),"soldier slaughter");near(first.hp,1000-power*3,"initial volley and nearby death explosion both damage survivor");check(second.hp==0&&second.pactMark==0,"dead body consumes its explosion once");float remaining=first.hp;tick(g);near(first.hp,remaining,"corpse cleanup cannot explode a second time");near(g.attackPeriod(),.48f*.55f,"soldier combat tempo");
        g=game(DOCTOR,1);g.hp=10;ActionGame.Enemy donor=g.enemies.get(0);check(g.professionPact(),"doctor selects a living donor");near(donor.hp,940,"doctor damages donor immediately");near(g.hp,58,"doctor steals actual damage instead of free emergency heal");hp=g.hp;int bottles=g.potions;g.potion();check(g.potions==bottles,"potion blocked without consumption");g.skill();near(g.hp,hp,"ordinary first aid cannot bypass harvesting lock");for(int i=0;i<60;i++)tick(g);check(g.hp>hp,"living donor supplies timed life extraction");g.x=100;hp=g.hp;float donorHp=donor.hp;for(int i=0;i<65;i++)tick(g);near(g.hp,hp,"out-of-range donor cannot heal remotely");near(donor.hp,donorHp,"broken tether does not drain");
        g=game(DOCTOR,0);g.hp=10;g.enemies.get(0).hp=5;g.professionPact();near(g.hp,14,"overkill does not manufacture life from a dying donor");g=game(DOCTOR,0);check(g.professionPact(),"full health still permits aggressive harvesting");
        g=game(MECHANIC,1);g.skillCd=5;hp=g.hp;check(g.professionPact(),"mechanic enslaves living engine");near(g.skillCd,0,"machine initially readies tool");near(hp-g.hp,g.maxHp()*.1f,"mechanic upfront cost");g.skillCd=5;float enemyHp=g.enemies.get(0).hp;for(int i=0;i<30;i++)tick(g);check(g.enemies.get(0).hp<enemyHp&&g.skillCd<4.1f,"actual grinding powers cooldown reduction");g.skillCd=0;hp=g.hp;g.skill();near(hp-g.hp,g.maxHp()*.04f,"overclock skill still pays life");near(g.skillCd,6.2f*.45f,"overclock period");g.skillCd=0;g.hp=g.maxHp()*.04f;hp=g.hp;g.skill();check(g.hp==hp&&g.skillCd==0,"lethal tool cost rejected");
        g=game(MECHANIC,0);ActionGame.Enemy engine=g.enemies.get(0),bystander=new ActionGame.Enemy(g.nextId++,0,720,600,1000);g.enemies.add(bystander);g.professionPact();engine.hp=1;for(int i=0;i<31;i++)tick(g);near(bystander.hp,1000-g.damage()*2,"spent living engine explodes and hurts bystander");
        g=game(MINER,2);power=g.damage();hp=g.hp;ActionGame.Enemy buried=g.enemies.get(0);g.professionPact();near(buried.hp,1000-power*1.2f,"burial begins with impact");near(g.pactWard,35,"temporary ward retained");near(g.careerWard,12,"ordinary specialization remains separate");for(int i=0;i<481;i++)tick(g);near(buried.hp,1000-power*10.4f,"eight crush pulses and final collapse, including last pulse");check(buried.pactMark==0&&g.pactWard==0,"burial and ward expire");
        g=game(BOXER,0);ActionGame.Enemy victim=g.enemies.get(0);g.professionPact();hit(g,20);hit(g,20);hit(g,20);near(victim.hp,1000-24*1.8f-36-41-46,"focused strikes grow on same victim");check(victim.pactStacks==3,"third blow disables fighting force");victim.x=g.x+40;victim.state=1;victim.timer=.001f;victim.stun=0;g.invulnerable=0;hp=g.hp;g.hitStop=0;g.update(1f/60,new ActionGame.Input());near(hp-g.hp,9,"broken opponent deals half damage even against vulnerable boxer");
        g=new ActionGame();g.selectHero(1);g.experience[1]=160;g.chooseCareer(BOXER,1,0,true);g.start(1);check(!g.professionPact()&&g.pactCd==0,"carbine cannot use close-quarters dismembering technique");
        g=game(MERCHANT,0);g.bank=500;g.loot=29;check(!g.professionPact()&&g.loot==29&&g.bank==500,"merchant cannot spend shared bank");g.loot=30;g.hp=20;g.professionPact();check(g.loot==0&&g.bank==500,"only current run currency is paid");near(g.hp,20,"no free healing from merely purchasing a contract");hit(g,20);near(g.hp,26,"debt takes actual victim life");g.enemies.get(0).hp=190;g.enemies.add(new ActionGame.Enemy(g.nextId++,0,1000,100,1000));hit(g,1);check(g.loot==12,"collecting a life pays its bounty once");int coins=g.loot;tick(g);check(g.loot==coins,"no duplicate bounty on cleanup");
        g=game(REPORTER,0);ActionGame.Enemy subject=g.enemies.get(0);boss=new ActionGame.Enemy(g.nextId++,3,750,500,1000);boss.state=1;boss.timer=.8f;g.enemies.add(boss);subject.state=1;subject.timer=.1f;g.professionPact();check(subject.state==0&&boss.state==1,"death notice interrupts ordinary subject, not boss");hit(g,20);near(subject.hp,980,"direct attack stays direct");near(boss.hp,990,"half the pain transmits to another named subject");near(subject.pactDebt,7,"written death accumulates deferred damage");near(boss.pactDebt,0,"echo cannot recursively create another death debt");for(int i=0;i<361;i++)tick(g);near(subject.hp,973,"death notice settles its stored injury on expiry");near(boss.hp,990,"expiry cannot recursively spread again");
        g=game(DOCTOR,0);g.enemies.get(0).x=100;hp=g.hp;check(!g.professionPact()&&g.pactCd==0&&g.hp==hp,"no target rejects atomically");g.enemies.get(0).x=620;g.blocks.add(new ActionGame.Block(580,570,20,60,0));check(!g.professionPact(),"solid obstruction prevents initial targeting");
        for(int job:new int[]{MECHANIC,MINER}){g=game(job,0);ActionGame.Enemy captive=g.enemies.get(0);g.professionPact();captive.stun=0;captive.state=0;float x=captive.x,y=captive.y;g.update(.05f,new ActionGame.Input());check(captive.x==x&&captive.y==y&&captive.state==0,"bound ordinary victim cannot move or start an attack");}
        g=game(MINER,0);boss=g.enemies.get(0);boss.type=3;boss.x=700;boss.stun=0;g.professionPact();boss.stun=0;boss.state=1;boss.timer=1;g.update(.05f,new ActionGame.Input());near(boss.timer,.975f,"buried boss still acts, at half tempo");
        g=game(MECHANIC,0);boss=g.enemies.get(0);boss.type=3;g.professionPact();boss.stun=0;boss.state=1;boss.timer=1;g.update(.05f,new ActionGame.Input());near(boss.timer,.95f,"living engine cannot immobilize a boss");
        System.out.println("PASS executions, death chains, donor extraction, living engine, burial, disabling blows, life debt and death notices");
    }
    private static void synergies()throws Exception{
        ActionGame g=new ActionGame();g.experience[0]=160;g.chooseCareer(MINER,2,1,true);g.bindSoul(2,1);g.relicOwned=RelicSystem.ALL;g.equipRelics(3,6);g.start(1);arena(g);g.dodge(0,-1);g.rollTime=0;float hp=g.hp;check(g.professionPact(),"bound miner pact");near(g.soulEnergy,40,"pact blast does not self-charge existing soul");near(g.relicEcho,3,"pact blast cannot consume copper bell");near(hp-g.hp,g.maxHp()*.18f,"soul sacrifice relic does not discount occupational price");near(g.corruption,0,"occupational cost does not silently create soul corruption");
        g=new ActionGame();g.experience[0]=160;g.chooseCareer(DOCTOR,2,4,true);g.bindSoul(2,1);g.relicOwned=RelicSystem.ALL;g.equipRelics(4,0);g.start(1);arena(g);g.hp=10;g.corruption=40;g.soulQuiet=3;float expected=10+g.damage()*2.5f*.8f*.88f*1.1f*1.12f;g.professionPact();near(g.hp,expected,"initial forbidden treatment obeys existing healing factors");g.soulSkill();hp=g.hp;hit(g,20);near(g.hp,hp,"blood pact lifesteal cannot bypass treatment lock");check(g.soulBuff>0&&g.pactTime>0,"soul and occupational forbidden states coexist");
        System.out.println("PASS pact/soul/relic combinations, healing lock, no hidden soul cost or amplification loop");
    }
    private static void persistence()throws Exception{
        for(int job=POLICE;job<=REPORTER;job++){
            ActionGame g=game(job,0);if(job==DOCTOR)g.hp=10;if(job==MERCHANT)g.loot=30;check(g.professionPact(),"cast for persistence");if(job==MINER)hurt(g,10);g.pause();float time=g.pactTime,cd=g.pactCd,hp=g.hp,ward=g.pactWard;for(int i=0;i<30;i++)tick(g);near(g.pactTime,time,"paused debt freezes");near(g.pactCd,cd,"paused cooldown freezes");
            ActionGame a=ActionSave.decode(ActionSave.encode(g));near(a.hp,hp,"restore never pays or heals again");near(a.pactWard,ward,"restore never refills equipment");near(a.pactTime,time,"remaining penalty restored");near(a.enemies.get(0).pactMark,g.enemies.get(0).pactMark,"victim mark restored");near(a.enemies.get(0).pactTick,g.enemies.get(0).pactTick,"pulse phase restored");a.room=2;a.generateRoom();near(a.pactTime,time,"room transition cannot erase debt");near(a.pactCd,cd,"room transition cannot refresh cooldown");near(a.pactWard,ward,"room transition cannot refill temporary shield");
            a.pause();a.abandon();a.returnCamp();check(a.pactTime==0&&a.pactCd==0&&a.pactWard==0&&a.pactEnabled(),"camp ends run state but retains choice");a.start(12);check(a.pactCd==0&&a.pactTime==0,"next run starts clean");
            if(ProfessionPacts.COST[job]>0){a.hp=a.maxHp()*ProfessionPacts.COST[job];float before=a.hp;check(!a.professionPact()&&a.hp==before&&a.pactCd==0,"unaffordable life cost refused atomically");}
        }
        ActionGame g=game(MINER,2);g.professionPact();byte[] data=ActionSave.encode(g);reject(data,"pactWard","36");reject(data,"pactTime","9");reject(data,"pactCd","33");reject(data,"pactTime","NaN");reject(data,"pactCd","0");reject(data,"careerPact0","false");reject(data,"careerPact1","true");
        g=game(POLICE,1);g.professionPact();reject(ActionSave.encode(g),"pactWard","1");g=new ActionGame();g.experience[0]=160;g.chooseCareer(POLICE,1,0,true);reject(ActionSave.encode(g),"pactCd","1");
        g=new ActionGame();g.experience[0]=160;g.chooseCareer(MECHANIC,1,4);g.bindSoul(2,1);g.start(1);g.soulSkill();data=edit(ActionSave.encode(g),"version","6");ActionGame old=ActionSave.decode(data);check(old.isSpec(MECHANIC,1)&&old.background()==4&&old.soulBuff>0&&!old.pactEnabled()&&old.pactCd==0,"v6 migration preserves ordinary career and soul, defaults pact off");
        g=game(REPORTER,0);g.professionPact();hit(g,20);data=ActionSave.encode(g);ActionGame restored=ActionSave.decode(data);near(restored.enemies.get(0).pactDebt,7,"deferred death survives save");for(int i=0;i<361;i++){tick(g);tick(restored);}near(restored.enemies.get(0).hp,g.enemies.get(0).hp,"resumed death settles exactly once at original time");
        g=game(DOCTOR,0);g.hp=10;g.professionPact();data=ActionSave.encode(g);old=ActionSave.decode(edit(data,"version","7"));check(!old.pactEnabled()&&old.pactTime==0&&old.job()==DOCTOR&&old.hp==g.hp&&old.enemies.get(0).hp==g.enemies.get(0).hp,"v7 preserves combat progress but requires fresh selection for changed acts");
        reject(data,"pactEnemy0","9,1,0,0");reject(data,"pactEnemy0","1,1,3,0");reject(data,"pactEnemy0","1,1,0,7");reject(data,"pactEnemy0","0,1,0,0");
        System.out.println("PASS opt-in, costs never replay, penalty/cooldown across rooms, pause, v6 migration and corrupt-state rejection");
    }
    private static void combinations()throws Exception{
        int steps=0;
        for(int job=POLICE;job<=REPORTER;job++)for(int weapon=0;weapon<3;weapon++)for(int soul=0;soul<3;soul++)for(int spec=1;spec<=2;spec++){
            ActionGame g=new ActionGame();g.selectCustom(0);BuildSystem.Profile p=g.profile().copy();p.weapon=weapon;p.skill=(job+weapon)%3;p.origin=job%3;p.trait=weapon;g.customize(0,p);g.profile().xp=1200;g.chooseCareer(job,spec,job%7,true);g.bindSoul(soul,soul==0?0:spec-1);g.relicOwned=RelicSystem.ALL;g.equipRelics(4,8);
            for(int root:new int[]{0,4,8}){for(int i=0;i<3;i++)g.learn(root);for(int i=0;i<2;i++)g.learn(root+1);}g.learn(new int[]{2,3,6,7,10,11}[(job+weapon)%6]);g.start(job*100+weapon);g.loot=60;g.hp=g.maxHp()*.7f;ActionGame.Input in=new ActionGame.Input();in.attack=true;
            for(int t=0;t<720;t++){
                if(g.mode==ActionGame.Mode.RESULT){g.returnCamp();g.start(t+1);g.loot=60;}if(g.mode==ActionGame.Mode.REWARD)g.chooseReward(t%3);
                in.mx=(float)Math.sin(t*.04);in.my=(float)Math.cos(t*.03);if(t%90==0)g.professionPact();if(t%120==0)g.skill();if(t%190==0)g.soulSkill();if(t%75==0)g.dodge(in.mx,in.my);if(g.hp<30)g.potion();g.update(1f/60f,in);g.signals.clear();steps++;
                if(t%60==0){g=ActionSave.decode(ActionSave.encode(g));check(g.hp>=0&&g.hp<=g.maxHp()&&g.pactWard<=35&&g.pactTime<=ProfessionPacts.DURATION[job],"combined pact snapshot bounds");}
            }
        }
        System.out.println("PASS "+steps+" steps across 144 pact/weapon/soul/specialization builds with talents and relics");
    }
    public static void main(String[] args)throws Exception{choices();effects();synergies();persistence();combinations();System.out.println("PACT CHECKS PASSED: "+count);}
}
